class Hint {
   private int length = Integer.MAX_VALUE;

   public Hint() {
   }

   public int getLength() {
      return this.length;
   }

   public void setLength(int var1) {
      if (var1 > 0) {
         this.length = var1;
      }

   }

   public void superprivatefunction() {
      String var1 = "";
      StringBuilder var2 = new StringBuilder("");
      int var4 = Math.min(this.length, var1.length() / 2);

      for(int var5 = 0; var5 < var4 * 2; var5 += 2) {
         String var6 = var1.substring(var5, var5 + 2);
         var2.append((char)Integer.parseInt(var6, 16));
      }

      System.out.println(var2);

   }

}

public class Main {
   public static void main(String[] args) {
       Hint hint = new Hint();
       hint.superprivatefunction();
   }
}